/* ==========================================================
   PEQUENA FLEUR — script.js
   Este arquivo está bem comentado de propósito: a ideia é que
   você consiga ler de cima a baixo e entender não só O QUE o
   código faz, mas POR QUE ele foi escrito assim. Sempre que
   aparecer um conceito novo de JavaScript, tem um comentário
   explicando.
========================================================== */


/* ----------------------------------------------------------
   1) ESTADO DO JOGO
   "Estado" é só um nome chique para "as variáveis que guardam
   a situação atual do jogo". Em vez de espalhar várias
   variáveis soltas (como no projeto original), juntamos tudo
   dentro de UM objeto. Isso facilita passar o estado inteiro
   para funções e evita bagunça.
---------------------------------------------------------- */
const estado = {
  nome: "",
  raiosSol: 30,       // moeda do jogo
  floresColhidas: 0,  // "flores devolvidas ao mundo" — nosso placar de progresso
  faseFalaAtual: -1,  // controla qual fala da Fleur já foi mostrada
};

/* Cada semente é um objeto com as mesmas propriedades. Guardar
   tudo em um array (lista) de objetos é o padrão mais comum em
   JS para representar "várias coisas parecidas". */
const sementes = [
  { nome: "Girassol",          icone: "🌻", custo: 15, lucro: 35,  tempo: 8  },
  { nome: "Calêndula",         icone: "🌼", custo: 30, lucro: 70,  tempo: 14 },
  { nome: "Cravo-de-defunto",  icone: "🏵️", custo: 55, lucro: 130, tempo: 22 },
];

/* Quantidade de canteiros (espaços de plantio) que o jardim tem.
   Muda esse número se quiser um jardim maior. */
const NUMERO_DE_CANTEIROS = 3;

/* Cada posição do array representa um canteiro. Começam todos
   vazios: null significa "nenhuma semente plantada aqui". */
const canteiros = Array.from({ length: NUMERO_DE_CANTEIROS }, () => ({
  semente: null,     // qual objeto de `sementes` está plantado aqui
  plantadoEm: null,  // timestamp (Date.now()) de quando foi plantado
  pronto: false,     // true quando já pode ser colhido
}));

/* Falas da Fleur que vão aparecendo conforme o jogador avança.
   `minimo` é quantas flores colhidas são necessárias para a
   fala aparecer. Isso é o que dá a sensação de a história
   "andar" junto com o jogo. */
const falasFleur = [
  { minimo: 0,  texto: "Achei essas sementes debaixo de uma placa de metal enferrujada. Você acha que ainda funcionam?" },
  { minimo: 1,  texto: "Uma flor! Uma flor de verdade! Ninguém na cidade vai acreditar em mim..." },
  { minimo: 3,  texto: "As máquinas nunca vieram até aqui atrás. Acho que esse cantinho é só nosso." },
  { minimo: 6,  texto: "Trouxe mais terra de um lugar onde ainda chove. O jardim está ficando enorme!" },
  { minimo: 10, texto: "Sabe, antes de te ouvir eu achava que o mundo ia ser sempre cinza. Obrigada por provar que eu estava errada." },
  { minimo: 15, texto: "As pessoas da cidade estão vindo ver o jardim. Acho que... acho que estamos trazendo as flores de volta pra valer." },
];

/* Textos da introdução, mostrados um por vez antes de pedir o nome. */
const historiaIntro = [
  "Há muito tempo, as máquinas cobriram o mundo inteiro de metal e poeira. O céu ficou cinza. Ninguém mais se lembrava da cor das flores.",
  "Mas nas rachaduras de uma fábrica abandonada, uma menina chamada Fleur, de 13 anos, encontrou algo que ninguém via há gerações: um punhado de sementes adormecidas.",
  "Fleur não sabe, mas existe alguém que desperta junto com cada semente plantada: o espírito que vive dentro das flores. Esse espírito é você.",
];


/* ----------------------------------------------------------
   2) REFERÊNCIAS AOS ELEMENTOS DO HTML
   `document.getElementById` procura, dentro da página, o
   elemento que tem aquele id="..." no HTML. Guardamos essas
   referências em constantes para não ficar procurando de novo
   toda hora.
---------------------------------------------------------- */
const telaIntro       = document.getElementById("tela-intro");
const telaJogo        = document.getElementById("tela-jogo");

const textoHistoriaEl = document.getElementById("texto-historia");
const botaoContinuar  = document.getElementById("botao-continuar");
const passoHistoriaEl = document.getElementById("passo-historia");

const formNome        = document.getElementById("form-nome");
const inputNome       = document.getElementById("input-nome");

const boasVindasEl    = document.getElementById("boas-vindas");
const textoBoasVindas = document.getElementById("texto-boas-vindas");
const botaoEntrar     = document.getElementById("botao-entrar");

const botaoSol        = document.getElementById("botao-sol");
const txtSol          = document.getElementById("txt-sol");
const txtFlores       = document.getElementById("txt-flores");
const textoFleurEl    = document.getElementById("texto-fleur");

const canteirosEl     = document.getElementById("canteiros");
const listaSementesEl = document.getElementById("lista-sementes");


/* ----------------------------------------------------------
   3) INTRODUÇÃO — mostrar a história, depois pedir o nome
---------------------------------------------------------- */
let indiceHistoria = 0;

function mostrarProximaLinhaDaHistoria() {
  textoHistoriaEl.textContent = historiaIntro[indiceHistoria];
  indiceHistoria++;

  // Quando acabarem as falas, trocamos o botão "Continuar" pelo
  // formulário de nome escondendo um e mostrando o outro.
  if (indiceHistoria >= historiaIntro.length) {
    botaoContinuar.textContent = "Continuar";
    botaoContinuar.onclick = () => {
      passoHistoriaEl.classList.add("escondido");
      formNome.classList.remove("escondido");
      inputNome.focus();
    };
  }
}

botaoContinuar.addEventListener("click", mostrarProximaLinhaDaHistoria);
mostrarProximaLinhaDaHistoria(); // mostra a primeira linha assim que a página carrega

/* `addEventListener("submit", ...)` escuta o envio do formulário
   (clicar em "Confirmar" ou apertar Enter). Usamos
   `event.preventDefault()` para impedir que a página recarregue,
   que é o comportamento padrão de formulários HTML. */
formNome.addEventListener("submit", (event) => {
  event.preventDefault();

  // .trim() remove espaços em branco do início/fim do texto digitado
  const nomeDigitado = inputNome.value.trim();
  estado.nome = nomeDigitado || "Espírito";

  formNome.classList.add("escondido");
  boasVindasEl.classList.remove("escondido");

  // Template literal: o `${...}` dentro de crases insere uma
  // variável direto no meio do texto, sem precisar concatenar com +
  textoBoasVindas.textContent =
    `Boas-vindas, ${estado.nome}! Fleur está te esperando no jardim de sucata, ` +
    `com as mãos cheias de terra e uma sementinha na palma da mão.`;
});

botaoEntrar.addEventListener("click", iniciarJogo);


/* ----------------------------------------------------------
   4) INICIAR O JOGO
---------------------------------------------------------- */
function iniciarJogo() {
  telaIntro.classList.add("escondido");
  telaJogo.classList.remove("escondido");

  renderizarSementes();
  renderizarCanteiros();
  atualizarPlacar();
  atualizarFalaFleur();

  // setInterval executa uma função repetidamente, de tempos em
  // tempos (aqui, a cada 250 milissegundos). É assim que criamos
  // o "relógio" do jogo, que atualiza as barras de progresso dos
  // canteiros sem precisarmos ficar clicando em nada.
  setInterval(atualizarCanteiros, 250);
}


/* ----------------------------------------------------------
   5) RAIOS DE SOL (a moeda do jogo)
---------------------------------------------------------- */
function adicionarSol(valor) {
  estado.raiosSol += valor;
  atualizarPlacar();
}

function atualizarPlacar() {
  txtSol.textContent = estado.raiosSol;
  txtFlores.textContent = estado.floresColhidas;
}

botaoSol.addEventListener("click", () => adicionarSol(1));


/* ----------------------------------------------------------
   6) A LOJA DE SEMENTES
   `renderizarSementes` monta o HTML da loja a partir do array
   `sementes`. Sempre que os dados mudam (nesse jogo eles não
   mudam, mas em outros projetos mudam), você chama essa função
   de novo para atualizar a tela.
---------------------------------------------------------- */
function renderizarSementes() {
  // .map() transforma cada item do array `sementes` em um
  // pedaço de HTML (texto), e .join("") junta tudo em uma
  // única string grande.
  listaSementesEl.innerHTML = sementes
    .map((semente, indice) => `
      <div class="semente">
        <span class="semente-icone">${semente.icone}</span>
        <p class="semente-nome">${semente.nome}</p>
        <p class="semente-info">Custo: ${semente.custo} 🔆</p>
        <p class="semente-info">Rende: ${semente.lucro} 🔆 em ${semente.tempo}s</p>
        <button class="botao botao-plantar" data-indice="${indice}">Plantar</button>
      </div>
    `)
    .join("");

  // Depois de criar os botões, precisamos "escutá-los". Como eles
  // foram criados agora, procuramos todos com a classe
  // .botao-plantar e adicionamos um clique em cada um.
  listaSementesEl.querySelectorAll(".botao-plantar").forEach((botao) => {
    botao.addEventListener("click", () => {
      const indice = Number(botao.dataset.indice);
      plantar(sementes[indice]);
    });
  });
}

function plantar(semente) {
  if (estado.raiosSol < semente.custo) {
    atualizarFala("Fleur balança a cabeça: \"Ainda não temos energia suficiente pra essa aqui.\"");
    return;
  }

  // .find() procura, dentro do array, o primeiro item que
  // satisfaz a condição — aqui, o primeiro canteiro vazio.
  const canteiroLivre = canteiros.find((c) => c.semente === null);

  if (!canteiroLivre) {
    atualizarFala("Fleur diz: \"Não tem mais espaço livre no jardim agora...\"");
    return;
  }

  estado.raiosSol -= semente.custo;
  canteiroLivre.semente = semente;
  canteiroLivre.plantadoEm = Date.now();
  canteiroLivre.pronto = false;

  atualizarPlacar();
  renderizarCanteiros();
}


/* ----------------------------------------------------------
   7) OS CANTEIROS (onde as flores crescem)
---------------------------------------------------------- */
function renderizarCanteiros() {
  canteirosEl.innerHTML = canteiros
    .map((canteiro, indice) => {
      if (canteiro.semente === null) {
        return `
          <div class="canteiro canteiro-vazio">
            <span class="canteiro-icone">🌱</span>
            <p>Canteiro vazio</p>
          </div>
        `;
      }

      const textoBotao = canteiro.pronto ? "Colher" : "Crescendo...";

      return `
        <div class="canteiro">
          <span class="canteiro-icone">${canteiro.semente.icone}</span>
          <p class="canteiro-nome">${canteiro.semente.nome}</p>
          <div class="barra-progresso">
            <div class="barra-progresso-preenchida" data-barra="${indice}" style="width:0%"></div>
          </div>
          <p class="canteiro-tempo" data-tempo="${indice}"></p>
          <button class="botao botao-colher" data-indice="${indice}" ${canteiro.pronto ? "" : "disabled"}>
            ${textoBotao}
          </button>
        </div>
      `;
    })
    .join("");

  canteirosEl.querySelectorAll(".botao-colher").forEach((botao) => {
    botao.addEventListener("click", () => {
      colher(Number(botao.dataset.indice));
    });
  });
}

/* Chamada repetidamente pelo setInterval lá em `iniciarJogo`.
   Ela calcula quanto tempo já passou desde que cada flor foi
   plantada e atualiza a barrinha de progresso na tela. */
function atualizarCanteiros() {
  canteiros.forEach((canteiro, indice) => {
    if (canteiro.semente === null || canteiro.pronto) return;

    const segundosPassados = (Date.now() - canteiro.plantadoEm) / 1000;
    const proporcao = Math.min(segundosPassados / canteiro.semente.tempo, 1);

    const barra = document.querySelector(`[data-barra="${indice}"]`);
    const tempoEl = document.querySelector(`[data-tempo="${indice}"]`);
    if (barra) barra.style.width = `${proporcao * 100}%`;

    if (proporcao >= 1) {
      canteiro.pronto = true;
      renderizarCanteiros(); // reconstrói esse canteiro já com o botão "Colher" ativo
    } else if (tempoEl) {
      const restante = Math.ceil(canteiro.semente.tempo - segundosPassados);
      tempoEl.textContent = `Tempo restante: ${restante}s`;
    }
  });
}

function colher(indice) {
  const canteiro = canteiros[indice];
  if (!canteiro.pronto) return;

  adicionarSol(canteiro.semente.lucro);
  estado.floresColhidas++;

  // Esvazia o canteiro para poder plantar outra semente nele.
  canteiro.semente = null;
  canteiro.plantadoEm = null;
  canteiro.pronto = false;

  atualizarPlacar();
  renderizarCanteiros();
  atualizarFalaFleur();
}


/* ----------------------------------------------------------
   8) A FALA DA FLEUR
---------------------------------------------------------- */
function atualizarFala(texto) {
  textoFleurEl.textContent = texto;
}

/* Verifica, na lista `falasFleur`, qual é a fala mais avançada
   que o jogador já desbloqueou (comparando com floresColhidas)
   e mostra ela — mas só troca a fala na tela se for uma fala
   nova, pra não ficar "piscando" o texto sem motivo. */
function atualizarFalaFleur() {
  // .filter() cria um novo array só com os itens que passam no teste
  const desbloqueadas = falasFleur.filter((f) => estado.floresColhidas >= f.minimo);
  const faseAtual = desbloqueadas.length - 1;

  if (faseAtual !== estado.faseFalaAtual) {
    estado.faseFalaAtual = faseAtual;
    atualizarFala(desbloqueadas[faseAtual].texto);
  }
}


/* ----------------------------------------------------------
   9) A FLEUR ANDANDO PELA TELA
   Ideia: o sprite fica em position:fixed (definido no CSS) e
   aqui só mudamos duas coisas nele com JavaScript:
     - a posição horizontal (translateX), a cada frame;
     - qual imagem (walk1/walk2/stand) está sendo exibida, para
       simular o ciclo de passos andando.

   `requestAnimationFrame` é a forma correta de fazer animações
   em JS: o navegador chama a função pouco antes de desenhar
   cada novo quadro na tela (geralmente ~60 vezes por segundo),
   o que dá uma animação bem mais suave do que usar setInterval.
---------------------------------------------------------- */
function iniciarFleurAndando() {
  const sprite = document.getElementById("fleur-sprite");

  const velocidade = 55;       // pixels por segundo
  const larguraSprite = 90;    // largura aproximada já redimensionada (ver CSS: height 130px)

  let posX = 40;               // posição horizontal atual
  let direcao = 1;             // 1 = andando para a direita, -1 = para a esquerda
  let ultimoFrameEm = null;    // timestamp do quadro anterior, usado para calcular o delta
  let cronometroPasso = 0;     // acumula tempo para trocar de quadro a cada X ms
  let quadroAtual = 0;         // índice do array `sequenciaDeAndar` abaixo

  // As três imagens vêm embutidas como "data URI" (aquele texto
  // gigante começando com "data:image/png;base64,..."). Fizemos
  // isso em vez de usar arquivos separados (assets/stand.png etc.)
  // porque, ao visualizar o jogo dentro do chat, só o HTML é
  // carregado — arquivos de imagem à parte não são servidos junto.
  // Embutir a imagem direto no código garante que ela sempre apareça,
  // tanto aqui quanto quando você abrir o index.html sozinho.
  const SPRITE_PARADA = sprite.src; // já veio embutida no atributo src do HTML
  const SPRITE_PASSO_1 = "data:image/png;base64,";
  const SPRITE_PASSO_2 = "data:image/png;base64,";

  // Sequência pedida: parada -> erguendo a perna -> andando -> repete.
  // Isso dá um ciclo de passada com 3 quadros em vez de só 2.
  const sequenciaDeAndar = [SPRITE_PARADA, SPRITE_PASSO_1, SPRITE_PASSO_2];

  function passo(agora) {
    if (ultimoFrameEm === null) ultimoFrameEm = agora;
    // deltaTempo = quanto tempo passou desde o último quadro, em segundos
    const deltaTempo = (agora - ultimoFrameEm) / 1000;
    ultimoFrameEm = agora;

    // Limite direito considerando a largura da janela e do sprite
    const limiteDireito = window.innerWidth - larguraSprite;

    posX += velocidade * direcao * deltaTempo;

    // Ao bater numa das bordas, inverte o sentido
    if (posX >= limiteDireito) {
      posX = limiteDireito;
      direcao = -1;
    } else if (posX <= 0) {
      posX = 0;
      direcao = 1;
    }

    // Espelha o sprite horizontalmente quando anda para a esquerda.
    // O jogo de sinal (-1) inverte a imagem no eixo X.
    const espelhado = direcao === -1 ? -1 : 1;
    sprite.style.transform = `translateX(${posX}px) scaleX(${espelhado})`;

    // Troca de quadro a cada 180ms, avançando pela sequência e
    // voltando ao início quando chega no fim (por isso o `%`,
    // o operador de resto da divisão — é o truque clássico pra
    // fazer qualquer contador "dar a volta" e virar um loop).
    cronometroPasso += deltaTempo * 1000;
    if (cronometroPasso > 180) {
      cronometroPasso = 0;
      quadroAtual = (quadroAtual + 1) % sequenciaDeAndar.length;
      sprite.src = sequenciaDeAndar[quadroAtual];
    }

    requestAnimationFrame(passo);
  }

  requestAnimationFrame(passo);
}

iniciarFleurAndando();
